import test from 'node:test';
import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {compileOriginalSourceRegions,validateOriginalSourceRegions,createOriginalSourceRegionsState} from '../src/source-region-geometry.js';
import {createScientificPreparation} from '../../wordpress/sherloq-browser/assets/batch-scientific-preparation.js';
import {originalBatchTaskDomain} from '../../wordpress/sherloq-browser/assets/original-source-regions-batch.js';

// Actual descriptors emitted by the unmodified compiler, not signatures
// generated by the implementation under test. All source/geometry is synthetic.
const fixture=JSON.parse(await readFile(new URL('./fixtures/source-region-legacy-domains.json',import.meta.url),'utf8'));
for(const entry of fixture.cases)test('legitimate pre-native-envelope domain migrates: '+entry.name,async()=>{
 const input=structuredClone(entry.descriptor),before=structuredClone(input),restored=await compileOriginalSourceRegions(input),parent=input.ceiling?await compileOriginalSourceRegions(input.ceiling):null,canonical=await compileOriginalSourceRegions(input.snapshot,{ceiling:parent});
 assert.equal(restored.fingerprint,canonical.fingerprint);assert.deepEqual(restored.rect,canonical.rect);assert.deepEqual(restored.origin,canonical.origin);assert.equal(restored.countIncluded,input.countIncluded);
 for(let y=0;y<fixture.source.height;y++)assert.deepEqual(restored.originalRowIntervals(y),canonical.originalRowIntervals(y));
 assert.deepEqual(input,before,'transported historical provenance remains unchanged');assert.equal(restored.snapshot.fingerprint,input.snapshot.fingerprint);
 const transported=await compileOriginalSourceRegions(structuredClone(restored.descriptor));assert.equal(transported.fingerprint,restored.fingerprint);assert.deepEqual(transported.rect,restored.rect);
});

const fractional=fixture.cases.find(c=>c.name==='fractional').descriptor,nested=fixture.cases.find(c=>c.name==='nested-grandchild').descriptor;
for(const [label,mutate]of [
 ['domain hash',d=>{d.fingerprint='0'.repeat(64);}],
 ['rect',d=>{d.rect.x0++;}],
 ['origin',d=>{d.origin[0]++;}],
 ['width',d=>{d.width++;}],
 ['height',d=>{d.height++;}],
 ['count',d=>{d.countIncluded++;}],
 ['snapshot geometry',d=>{d.snapshot.zones[0].x0+=.1;d.snapshot.zones[0].polygon[0][0]+=.1;d.snapshot.zones[0].polygon[3][0]+=.1;}],
 ['snapshot hash',d=>{d.snapshot.fingerprint='0'.repeat(64);}],
 ['source',d=>{d.snapshot.sourceSha256='2'.repeat(64);}],
])test('legacy migration refuses tampered '+label,async()=>{const changed=structuredClone(fractional);mutate(changed);await assert.rejects(compileOriginalSourceRegions(changed),{code:'SOURCE_REGIONS_INVALID'});});

for(const [label,mutate]of [
 ['ceiling domain hash',d=>{d.ceiling.fingerprint='0'.repeat(64);}],
 ['ceiling rect',d=>{d.ceiling.rect.x0++;}],
 ['grandparent source',d=>{d.ceiling.ceiling.snapshot.sourceSha256='2'.repeat(64);}],
])test('legacy migration validates entire nested '+label,async()=>{const changed=structuredClone(nested);mutate(changed);await assert.rejects(compileOriginalSourceRegions(changed),{code:'SOURCE_REGIONS_INVALID'});});

test('new canonical descriptors also reject altered transported geometry',async()=>{const domain=await compileOriginalSourceRegions(fractional);for(const mutate of [d=>d.rect.x0++,d=>d.origin[1]++,d=>d.countIncluded++]){const changed=structuredClone(domain.descriptor);mutate(changed);await assert.rejects(compileOriginalSourceRegions(changed),{code:'SOURCE_REGIONS_INVALID'});}});
test('session snapshot identity remains unchanged and recompiles the corrected native rectangle',async()=>{const snapshot=await validateOriginalSourceRegions(fractional.snapshot),state=await createOriginalSourceRegionsState(fixture.source,{snapshot});assert.equal(state.snapshot().fingerprint,fractional.snapshot.fingerprint);assert.deepEqual((await compileOriginalSourceRegions(state.snapshot())).rect,{x0:3,y0:2,x1:28,y1:21});});
test('retained old batch preparation reaches canonical domain without model, RGB or provenance mutation',async()=>{const image=structuredClone(fixture.batchImage),saved=structuredClone(image.preparation),service=createScientificPreparation({clientFactory:async()=>{throw Error('A source scope must not start a model.');}});await service.prepare({images:[image],studies:[]});await service.dispose();assert.deepEqual(image.preparation,saved);const transported=await originalBatchTaskDomain(image,'inspection.histogram'),domain=await compileOriginalSourceRegions(transported);assert.deepEqual(domain.rect,{x0:3,y0:2,x1:28,y1:21});assert.notEqual(transported.fingerprint,saved.sourceRegionDomain.fingerprint);assert.equal(transported.snapshot.sourceSha256,image.sourceSha256);assert.deepEqual(image.preparation,saved);});
test('batch migration still refuses a different encoded source identity',async()=>{const image=structuredClone(fixture.batchImage);image.sourceSha256='2'.repeat(64);await assert.rejects(originalBatchTaskDomain(image,'inspection.histogram'),{code:'SOURCE_REGIONS_INVALID'});});
